// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0);
        vm.assume(amount <= address(this).balance);
        vm.deal(address(c), amount);
        vm.deal(caller, 0);
        bool ok;
        vm.prank(caller);
        try c.sendTo(address(0), amount) { ok = true; } catch { ok = false; }
        assertTrue(ok == false || caller == address(this));
    }
}
